(1, 1, '2020-07-20', 1, NULL, NULL, 'Urban Flood Forecasting System for Dhaka City study (reported local verification)', 'Reported urban flooding in Dhaka. Confidence=medium. Study reports this date and named Dhaka localities; verify against primary local records before high-stakes use. Source URL: https://www.preprints.org/manuscript/202409.0203', '2026-10-09 20:39:26'),
(2, 1, '2021-06-02', 1, NULL, NULL, 'Urban Flood Forecasting System for Dhaka City study (reported local verification)', 'Reported urban flooding in Dhaka. Confidence=medium. Study reports this date and named Dhaka localities; verify against primary local records before high-stakes use. Source URL: https://www.preprints.org/manuscript/202409.0203', '2026-10-09 20:39:26'),
(3, 1, '2022-10-24', 1, NULL, NULL, 'Urban Flood Forecasting System for Dhaka City study (field survey)', 'Reported urban flooding in Dhaka. Confidence=medium. Study reports this date and named Dhaka localities; verify against primary local records before high-stakes use. Source URL: https://www.preprints.org/manuscript/202409.0203', '2026-10-09 20:39:26'),
(4, 5, '2021-07-18', 1, NULL, NULL, 'National Remote Sensing Centre, ISRO', 'Heavy rain and flood-affected areas in Mumbai-Thane. Confidence=high. Official satellite mapping page identifies heavy-rain affected areas around Mumbai and Thane on 18 July 2021. Source URL: https://www.nrsc.gov.in/nrscnew/2021_Floods.php', '2026-10-09 20:39:26'),
(5, 5, '2021-07-23', 1, NULL, NULL, 'National Disaster Response Force, Government of India', 'Heavy rainfall and flooding in Mumbai and nearby districts. Confidence=medium. Official release dated 24 July describes heavy rainfall over the preceding days and flood rescue operations including Mumbai; event timing is regional. Source URL: https://www.ndrf.gov.in/en/pressrelease/flood-rescue-operation-ndrf-maharashtra', '2026-10-09 20:39:26'),
(6, 5, '2021-07-24', 1, NULL, NULL, 'National Disaster Response Force, Government of India', 'Heavy rainfall and flooding in Mumbai and nearby districts. Confidence=medium. Official release dated 24 July describes heavy rainfall over the preceding days and flood rescue operations including Mumbai; event timing is regional. Source URL: https://www.ndrf.gov.in/en/pressrelease/flood-rescue-operation-ndrf-maharashtra', '2026-10-09 20:39:26'),
(7, 6, '2020-01-01', 1, NULL, NULL, 'Jakarta government publication, Chronology of Jakarta Flooding in the Beginning of 2020', 'Jakarta New Year floods. Confidence=high. Official Jakarta publication documents inundation and continuing flood impacts from 1–4 January 2020. Source URL: https://jakita.jakarta.go.id/media/download/eng/edisi_1_2020.pdf', '2026-10-09 20:39:26'),
(8, 6, '2020-01-02', 1, NULL, NULL, 'Jakarta government publication, Chronology of Jakarta Flooding in the Beginning of 2020', 'Jakarta New Year floods. Confidence=high. Official Jakarta publication documents inundation and continuing flood impacts from 1–4 January 2020. Source URL: https://jakita.jakarta.go.id/media/download/eng/edisi_1_2020.pdf', '2026-10-09 20:39:26'),
(9, 6, '2020-01-03', 1, NULL, NULL, 'Jakarta government publication, Chronology of Jakarta Flooding in the Beginning of 2020', 'Jakarta New Year floods. Confidence=high. Official Jakarta publication documents inundation and continuing flood impacts from 1–4 January 2020. Source URL: https://jakita.jakarta.go.id/media/download/eng/edisi_1_2020.pdf', '2026-10-09 20:39:26'),
(10, 6, '2020-01-04', 1, NULL, NULL, 'Jakarta government publication, Chronology of Jakarta Flooding in the Beginning of 2020', 'Jakarta New Year floods. Confidence=high. Official Jakarta publication documents inundation and continuing flood impacts from 1–4 January 2020. Source URL: https://jakita.jakarta.go.id/media/download/eng/edisi_1_2020.pdf', '2026-10-09 20:39:26'),
(11, 7, '2021-07-12', 1, NULL, NULL, 'UK Flood Forecasting Centre annual review', 'London surface-water flash flooding. Confidence=high. Official review documents widespread London flooding on 12 July 2021. Source URL: https://www.gov.uk/government/publications/flood-forecasting-centre-annual-review-2021-to-2022/flood-forecasting-centre-annual-review-2021-to-2022', '2026-10-09 20:39:26'),
(12, 7, '2021-07-25', 1, NULL, NULL, 'UK Flood Forecasting Centre annual review', 'London surface-water flash flooding. Confidence=high. Official review documents widespread London flooding on 25 July 2021. Source URL: https://www.gov.uk/government/publications/flood-forecasting-centre-annual-review-2021-to-2022/flood-forecasting-centre-annual-review-2021-to-2022', '2026-10-09 20:39:26'),
(13, 8, '2021-08-29', 1, NULL, NULL, 'National Hurricane Center, NOAA', 'Hurricane Ida impacts near New Orleans. Confidence=medium. NOAA bulletin reports catastrophic storm surge, extreme winds and flash flooding in southeast Louisiana and locates Ida near New Orleans. Confirm exact city-level inundation before treating as a strictly local label. Source URL: https://www.nhc.noaa.gov/archive/2021/al09/al092021.public.015.shtml', '2026-10-09 20:39:26');
